// Static terrain chunk cache. Noise, variants and transition masks are generation-time data.
(function(root){
'use strict';
const size=32,files={grass:['grass1','grass2','grass3'],sand:['sand-floor1','sand-floor2','sand-floor3'],gravel:['darksand1','darksand2','darksand3'],stone:['stone1','stone2','stone3'],hill:['dune-wall-large','dune-wall-large','dune-wall-large'],mountain:['stone-wall-large','dacite-wall-large','carbon-wall-large'],water:['shallow-water','deep-water','shallow-water']},images={};let epoch=0,cacheGrid=null;const cache=new Map(),masks=[],blends=new Map();
const canvas=(w,h)=>{if(typeof OffscreenCanvas!=='undefined')return new OffscreenCanvas(w,h);if(document.createElement){const c=document.createElement('canvas');c.width=w;c.height=h;return c}return null};
for(const [type,names] of Object.entries(files))images[type]=names.map(name=>{const im=new Image();im.onload=()=>{epoch++;cache.clear();blends.clear()};im.onerror=()=>{epoch++;cache.clear();blends.clear()};im.src='assets/mindustry/terrain/'+name+'.png';return im});
const rank={grass:0,sand:1,gravel:2,stone:3,water:4,hill:5,mountain:6,road:-1};
function image(ctx,im,x,y,w,h){if(im?.complete&&im.naturalWidth)ctx.drawImage(im,x,y,w,h)}
function tile(ctx,type,v,x,y,wx=0,wy=0){ctx.fillStyle=World.TERRAIN[type].color;ctx.fillRect(x,y,size,size);if(type==='road')return;
 if(type==='hill'||type==='mountain'){image(ctx,images[type==='hill'?'gravel':'stone'][v],x,y,size,size);const im=images[type][v];if(im?.complete&&im.naturalWidth)ctx.drawImage(im,(wx%2)*32,(wy%2)*32,32,32,x,y,size,size);ctx.fillStyle=type==='hill'?'#b7a07b55':'#10182d45';ctx.fillRect(x,y,size,size)}else {image(ctx,images[type][v],x,y,size,size);if(type==='water'||type==='gravel'){ctx.fillStyle=type==='water'?'#258ab626':'#c3ac8560';ctx.fillRect(x,y,size,size)}}
}
function blend(type,v,side){const key=type+v+side;if(blends.has(key))return blends.get(key);const c=canvas(size,size);if(!c)return null;const ctx=c.getContext('2d');tile(ctx,type,v,0,0);if(!masks[side]){const mask=canvas(size,size),m=mask.getContext('2d');for(let y=0;y<size;y++)for(let x=0;x<size;x++){const distance=[size-1-x,size-1-y,x,y][side],along=side%2?x:y,depth=5+(Math.floor(along/4)%3);if(distance<depth){m.fillStyle='rgba(255,255,255,'+(.65*(1-distance/depth))+')';m.fillRect(x,y,1,1)}}masks[side]=mask}ctx.globalCompositeOperation='destination-in';ctx.drawImage(masks[side],0,0);blends.set(key,c);return c}
function drawTile(ctx,g,x,y,px,py){const k=g.key(x,y),type=g.terrainAt(x,y),v=type==='water'?(g.transitions[k]?0:1):type==='hill'||type==='mountain'?g.variants[g.key(x-x%2,y-y%2)]:g.variants[k];tile(ctx,type,v,px,py,x,y);if(type==='road')return;const mask=g.transitions[k];for(let i=0;i<4;i++)if(mask&(1<<i)){const [dx,dy]=World.CARDINAL[i],other=g.terrainAt(x+dx,y+dy);if(other==='road'||rank[other]<=rank[type])continue;const sprite=blend(other,g.variants[g.key(x+dx,y+dy)]||0,i);if(sprite)ctx.drawImage(sprite,px,py)}
 if((type==='hill'||type==='mountain')&&g.inside(x,y+1)&&g.passable(x,y+1)){ctx.fillStyle=type==='hill'?'#292b3440':'#1016208c';ctx.fillRect(px,py+27,size,5);if(!g.inside(x,y-1)||g.passable(x,y-1)){ctx.fillStyle='#b2a79255';ctx.fillRect(px,py,32,2)}}
}
function chunk(g,cx,cy,res){const key=res+':'+cx+','+cy,entry=cache.get(key);if(entry&&entry.epoch===epoch&&entry.version===g.terrainVersion){cache.delete(key);cache.set(key,entry);return entry.canvas}const n=g.chunkSize,c=canvas(n*res,n*res);if(!c)return null;const ctx=c.getContext('2d');ctx.imageSmoothingEnabled=false;ctx.scale(res/size,res/size);for(let y=0;y<n;y++)for(let x=0;x<n;x++){const xx=cx*n+x,yy=cy*n+y;if(g.inside(xx,yy))drawTile(ctx,g,xx,yy,x*size,y*size)}cache.set(key,{canvas:c,epoch,version:g.terrainVersion});while(cache.size>128||[...cache.values()].reduce((sum,e)=>sum+e.canvas.width*e.canvas.height*4,0)>64*1024*1024)cache.delete(cache.keys().next().value);return c}
function draw(ctx,g,x0,y0,x1,y1,screen,scale){if(cacheGrid!==g){cacheGrid=g;cache.clear()}const n=g.chunkSize;for(let cy=Math.floor(y0/n);cy<=Math.floor((y1-1)/n);cy++)for(let cx=Math.floor(x0/n);cx<=Math.floor((x1-1)/n);cx++){const res=scale<16?8:32,c=chunk(g,cx,cy,res);if(c){const [x,y]=screen(cx*n,cy*n),[ex,ey]=screen(Math.min(g.width,(cx+1)*n),Math.min(g.height,(cy+1)*n));ctx.drawImage(c,0,0,Math.min(n,g.width-cx*n)*res,Math.min(n,g.height-cy*n)*res,Math.round(x),Math.round(y),Math.round(ex)-Math.round(x),Math.round(ey)-Math.round(y))}else{for(let y=Math.max(y0,cy*n);y<Math.min(y1,(cy+1)*n);y++)for(let x=Math.max(x0,cx*n);x<Math.min(x1,(cx+1)*n);x++){const [px,py]=screen(x,y),type=g.terrainAt(x,y);ctx.fillStyle=World.TERRAIN[type].color;ctx.fillRect(px,py,scale,scale);image(ctx,images[type]?.[g.variants[g.key(x,y)]],px,py,scale,scale)}}}}
root.TerrainArt={draw,images,cache,chunkPixels:512};
})(globalThis);
